/* VITO TAP published profile — shared behaviour (generated by the Worker). */
(function () {
  'use strict';

  function toggleSide(card) {
    card.setAttribute(
      'data-side',
      card.getAttribute('data-side') === 'back' ? 'front' : 'back',
    );
  }

  document.querySelectorAll('.vt-card').forEach(function (card) {
    card.addEventListener('click', function (event) {
      if (event.target.closest('[data-copy]')) return;
      toggleSide(card);
    });
    card.addEventListener('keydown', function (event) {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      if (event.target.closest('[data-copy]')) return;
      event.preventDefault();
      toggleSide(card);
    });
  });

  var checkTimer = null;

  function flashCheck(button) {
    var copy = button.querySelector('.vt-glyph-copy');
    var check = button.querySelector('.vt-glyph-check');
    var status = document.getElementById('vt-copy-status');
    if (status) status.textContent = 'کپی شد';
    if (copy && check) {
      copy.hidden = true;
      check.hidden = false;
    } else {
      // Text-only buttons (e.g. field copy) swap their label instead.
      if (!button.dataset.originalLabel) {
        button.dataset.originalLabel = button.textContent || 'کپی';
      }
      button.textContent = '✓';
    }
    if (checkTimer) window.clearTimeout(checkTimer);
    checkTimer = window.setTimeout(function () {
      if (copy && check) {
        copy.hidden = false;
        check.hidden = true;
      } else if (button.dataset.originalLabel) {
        button.textContent = button.dataset.originalLabel;
      }
      if (status) status.textContent = '';
    }, 1800);
  }

  function fallbackCopy(value) {
    var area = document.createElement('textarea');
    area.value = value;
    area.setAttribute('readonly', '');
    area.style.position = 'fixed';
    area.style.opacity = '0';
    document.body.appendChild(area);
    area.select();
    try {
      document.execCommand('copy');
    } catch (err) {
      /* clipboard unavailable — nothing else to try */
    }
    document.body.removeChild(area);
  }

  document.addEventListener('click', function (event) {
    var button = event.target.closest('[data-copy]');
    if (!button) return;
    event.stopPropagation();
    var value = button.getAttribute('data-copy') || '';
    if (!value) return;
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(value).then(
        function () {
          flashCheck(button);
        },
        function () {
          fallbackCopy(value);
          flashCheck(button);
        },
      );
    } else {
      fallbackCopy(value);
      flashCheck(button);
    }
  });
})();
